"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["30603"],{50852(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.ponto_resolucao_invalido","status":422,"titulo":"Ponto de resolu\xe7\xe3o do fato fora do conjunto can\xf4nico de fases"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.ponto_resolucao_invalido","requisitos":["UNI-REQ-0143"],"oQueAconteceu":["O ponto de resolu\xe7\xe3o \xe9 a fase do processo em que o valor do fato fica conhecido (UNI-REQ-0143), e s\xf3 pode ser uma das fases can\xf4nicas. O `pontoResolucao` do cadastro (`POST /api/configuracao/admin/fatos-candidato`, `POST /api/configuracao/admin/fatos-candidato/derivados` ou `POST /api/configuracao/admin/fatos-candidato/agregados`) ou da altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) de um fato do administrador n\xe3o \xe9 o c\xf3digo de nenhuma delas. A compara\xe7\xe3o diferencia mai\xfasculas de min\xfasculas, e os espa\xe7os nas pontas s\xe3o desconsiderados.","A recusa vem na lista `errors` da resposta, com `field` igual a `pontoResolucao`. Nada \xe9 gravado. Um ponto vazio recebe [a recusa de ponto de resolu\xe7\xe3o obrigat\xf3rio](/erros/uniplus.configuracao.fato_candidato.ponto_resolucao_obrigatorio), exceto na altera\xe7\xe3o da defini\xe7\xe3o de um fato de sistema, em que \xe9 ignorado. No fato de sistema, que s\xf3 aceita mudar o nome, a descri\xe7\xe3o, a forma de exibi\xe7\xe3o e a prote\xe7\xe3o de dados, um ponto de resolu\xe7\xe3o diferente do atual recebe a recusa de [defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)."],"comoResolver":["Use o c\xf3digo de uma fase can\xf4nica, escrito como na lista do vocabul\xe1rio (`GET /api/configuracao/vocabularios/fases-canonicas`), em mai\xfasculas e com sublinhado."],"ondeAparece":["Cadastro de um fato do cat\xe1logo (declarado, derivado ou resumo de grupo)","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);